    /// contracts/shared-data/v1/source-manners-v1.json: How Binario asks every public source, on Android and on the
    /// iPhone: the User-Agent (the app by name, version and platform, never a browser's), the statuses that are a
    /// refusal and the pause after one without Retry-After, and the circuit breaker (failures in a row, first and
    /// longest pause, longest Retry-After honoured).
    public enum SourceManners {
        public static let userAgent: String = "Binario/<version> (<platform>; rail timetable app)"
        public static let refusalStatuses: Set<Int> = [403, 429]
        public static let refusalPauseSeconds: Double = 900
        public static let maximumRetryAfterSeconds: Double = 3600
        public static let failureThreshold: Int = 3
        public static let baseOpenSeconds: Double = 60
        public static let maximumOpenSeconds: Double = 900
    }

